// Isolated browser fixture. No real Firebase SDK, credentials, or inventory writes.
module.exports=async function mockFirebase(page){
 await page.addInitScript(()=>{window.__pantryMock={user:null,docs:[],writes:0,watchers:[],errorWatchers:[],authWatchers:[],failOnce:false,replyLostOnce:false};});
 await page.route('**/assets/firebase-config.js',route=>route.fulfill({contentType:'text/javascript',body:'export const firebaseConfig={apiKey:"fixture",projectId:"fixture"};'}));
 await page.route('https://www.gstatic.com/firebasejs/**',async route=>{
  const name=new URL(route.request().url()).pathname.split('/').pop();let body;
  if(name==='firebase-app.js')body='export const initializeApp=()=>({});';
  else if(name==='firebase-auth.js')body=`const m=window.__pantryMock;export const getAuth=()=>({});export class GoogleAuthProvider{};export const onAuthStateChanged=(a,fn)=>{m.authWatchers.push(fn);setTimeout(()=>fn(m.user),0)};export const signInWithPopup=async()=>{m.user={uid:'fixture-user',email:'fixture@example.test'};m.authWatchers.forEach(fn=>fn(m.user))};export const signInWithRedirect=signInWithPopup;export const getRedirectResult=async()=>null;export const signOut=async()=>{m.user=null;m.authWatchers.forEach(fn=>fn(null))};`;
  else if(name==='firebase-firestore.js')body=`const m=window.__pantryMock;const snapshot=()=>({docs:m.docs.map(d=>({id:d.id,data:()=>({...d.data})}))});const emit=()=>m.watchers.forEach(fn=>fn(snapshot()));export const getFirestore=()=>({});export const collection=(db,...parts)=>({path:parts.join('/')});export const doc=(col,id)=>({path:col.path+'/'+id,id});export const serverTimestamp=()=>({fixtureTimestamp:true});export const onSnapshot=(col,fn,onError)=>{m.watchers.push(fn);if(onError)m.errorWatchers.push(onError);setTimeout(()=>fn(snapshot()),0);return ()=>{m.watchers=m.watchers.filter(x=>x!==fn);m.errorWatchers=m.errorWatchers.filter(x=>x!==onError)}};export const addDoc=async(col,data)=>{m.docs.push({id:'ordinary-'+m.writes++,data});emit()};export const updateDoc=async(ref,data)=>{Object.assign(m.docs.find(d=>d.id===ref.id).data,data);emit()};export const deleteDoc=async ref=>{m.docs=m.docs.filter(d=>d.id!==ref.id);emit()};export const runTransaction=async(db,fn)=>{if(m.failOnce){m.failOnce=false;throw Error('Simulated unavailable connection.')}const changes=[];const result=await fn({get:async ref=>{const d=m.docs.find(d=>d.id===ref.id);return {exists:()=>!!d,data:()=>d?.data}},set:(ref,data)=>changes.push(()=>{m.docs.push({id:ref.id,data,path:ref.path});m.writes++}),update:(ref,data)=>changes.push(()=>{Object.assign(m.docs.find(d=>d.id===ref.id).data,data);m.writes++})});changes.forEach(fn=>fn());emit();if(m.replyLostOnce){m.replyLostOnce=false;throw Error('Simulated lost reply.')}return result};`;
  else throw Error('Unexpected Firebase fixture module '+name);
  await route.fulfill({contentType:'text/javascript',body});
 });
};
